template< class... Ts >

using common_comparison_category_t = common_comparison_category<Ts...>::type;

 (since C++20)

namespace detail
{
    template<unsigned int>
    struct common_cmpcat_base     { using type = void; };
    template<>
    struct common_cmpcat_base<0u> { using type = std::strong_ordering; };
    template<>
    struct common_cmpcat_base<2u> { using type = std::partial_ordering; };
    template<>
    struct common_cmpcat_base<4u> { using type = std::weak_ordering; };
    template<>
    struct common_cmpcat_base<6u> { using type = std::partial_ordering; };
} // namespace detail

template<class...Ts>
struct common_comparison_category :
    detail::common_cmpcat_base<(0u | ... |
        (std::is_same_v<Ts, std::strong_ordering>  ? 0u :
         std::is_same_v<Ts, std::weak_ordering>    ? 4u :
         std::is_same_v<Ts, std::partial_ordering> ? 2u : 1u)
    )> {};

examples.code:
#include <compare>
#include <concepts>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    static_assert(std::three_way_comparable<int>);
    using Category =
        std::common_comparison_category_t<std::strong_ordering, std::weak_ordering>;
    static_assert(std::is_same_v<Category, std::weak_ordering>);
    auto strong = std::strong_order(1, 2);
    auto weak = std::weak_order(1, 2);
    auto partial = std::partial_order(1.0, 2.0);
    assert(strong == std::strong_ordering::less && weak == std::weak_ordering::less);
    assert(partial == std::partial_ordering::less);
    assert(std::is_lt(strong) && std::is_lteq(strong) && !std::is_eq(strong) &&
        std::is_neq(strong));
    assert(std::is_gt(2 <=> 1) && std::is_gteq(2 <=> 1));
    assert(std::compare_strong_order_fallback(1, 2) < 0);
    assert(std::compare_partial_order_fallback(1, 2) < 0);
}
